nl=$(printf "\nx"); nl=${nl%x}; real() { r=$(pwd -P && echo .) || return 1; r=${r%.}; r=${r%"$nl"}; }; cd -P -- "$HOME" && real || { echo "cannot resolve the home folder" >&2; exit 3; }; H=$r; st=0; for p do case $p in /*) ;; *) echo "not absolute: $p" >&2; st=4; continue;; esac; parent=${p%/*}; name=${p##*/}; [ -n "$parent" ] || parent=/; case $name in ""|.|..) echo "refusing: $p" >&2; st=4; continue;; esac; if cd -P -- "$parent" && real; then case $r in /) t=/$name;; *) t=$r/$name;; esac; case "$H/" in "$t"/*) echo "Refusing to delete $t" >&2; st=5; continue;; esac; rm -rf -- "./$name" || st=1; else st=1; fi; done; exit $st
